void native_byte_and_size_controls() {
  assert(minera::pripel_trace_levenshtein(std::string("a\0@b",5), std::string("a\0@c",5)) == 1);
  assert(minera::pripel_trace_levenshtein(std::string(150000, 'x'), std::string(150000, 'x')) == 0);
  const auto raw = std::string("\xff@\xed\xa0\x80",5);
  assert(minera::pripel_trace_levenshtein(raw,raw) == 0);
  assert(minera::pripel_encoded_trace_length(raw) == 2);
}
